fn remove_key(&mut self, key: &Key) {
    use crate::time::wheel::Stack;

    // Special case the `expired` queue
    if self.slab[*key].expired {
        self.expired.remove(key, &mut self.slab);
    } else {
        self.wheel.remove(key, &mut self.slab);
    }
}

